def solve(x):
    visited = set()
    stack = [x["start"]]
    result = set()

    while stack:
        current = stack.pop()
        if current not in visited:
            visited.add(current)
            result.add(current)
            for neighbor in x["edges"]:
                if neighbor[0] == current:
                    stack.append(neighbor[1])

    return sorted(result)
